1	"use server";
2	
3	import { randomBytes } from "node:crypto";
4	import { revalidatePath } from "next/cache";
5	import { z } from "zod";
6	import bcrypt from "bcryptjs";
7	import type { Role } from "@prisma/client";
8	import { db } from "./db";
9	import { requireAdmin } from "./auth";
10	import { normalizeEmail } from "./email-normalize";
11	import { normalizeCidr } from "./firewall-rules";
12	import { GRANTABLE_AREAS } from "./staff-grants";
13	import type { Area } from "./rbac";
14	import { createCompanyMailbox, listCompanyMailboxes } from "./actions-company-mail";
15	import { normalizeLocalPart } from "./company-mail-core";
16	import { mailcowConfigured } from "./mailcow";
17	
18	const roleSchema = z.enum(["CUSTOMER", "SUPPORT", "BILLING", "ADMIN"]);
19	
20	/**
21	 * Promote/demote a user's role. ADMIN-only, audit-logged. An admin can't
22	 * change their own role (prevents locking yourself out of admin).
23	 */
24	export async function setUserRole(
25	  userId: string,
26	  role: Role,
27	): Promise<{ ok?: boolean; error?: string }> {
28	  const admin = await requireAdmin();
29	
30	  const parsed = roleSchema.safeParse(role);
31	  if (!parsed.success) return { error: "Invalid role." };
32	
33	  if (userId === admin.id) return { error: "You can't change your own role." };
34	
35	  const target = await db.user.findUnique({ where: { id: userId } });
36	  if (!target) return { error: "User not found." };
37	  if (target.role === parsed.data) return { ok: true };
38	
39	  await db.user.update({ where: { id: userId }, data: { role: parsed.data } });
40	  await db.auditLog.create({
41	    data: {
42	      userId: admin.id,
43	      action: "staff.setRole",
44	      detail: `${target.email}: ${target.role} → ${parsed.data}`,
45	    },
46	  });
47	
48	  revalidatePath("/admin/staff");
49	  revalidatePath(`/admin/users/${userId}`);
50	  return { ok: true };
51	}
52	
53	function isGrantableArea(area: unknown): area is Area {
54	  return GRANTABLE_AREAS.some((g) => g.area === area);
55	}
56	
57	/**
58	 * Best-effort: try `${base}@nxeon.cloud`, then `${base}2@`, `${base}3@`, … up
59	 * to 20 attempts, stopping at the first that doesn't already exist. Returns
60	 * null (never throws) if Mailcow isn't configured or every attempt fails for
61	 * a reason OTHER than the address being taken — createEmployee must still
62	 * succeed even when this can't; a missing personal mailbox is something an
63	 * admin can create by hand later, but a missing account is not recoverable
64	 * the same way.
65	 */
66	async function provisionPersonalMailbox(
67	  employeeName: string,
68	): Promise<{ address: string; password: string } | null> {
69	  if (!mailcowConfigured()) return null;
70	  const base = normalizeLocalPart(employeeName.trim().split(/\s+/)[0] ?? "") ?? "staff";
71	  for (let i = 0; i < 20; i++) {
72	    const localPart = i === 0 ? base : `${base}${i + 1}`;
73	    const res = await createCompanyMailbox(localPart, employeeName);
74	    if (res.ok) return { address: res.address, password: res.password };
75	    if (!res.error.includes("already exists")) return null;
76	  }
77	  return null;
78	}
79	
80	/**
81	 * Create a Role.EMPLOYEE account with ZERO access (see lib/staff-grants.ts —
82	 * EMPLOYEE has no area until an explicit StaffGrant exists). The temp password
83	 * is returned to the caller exactly once; only its bcrypt hash is ever stored,
84	 * at the same cost factor (12) as every other password write in this codebase
85	 * (lib/actions.ts's register, lib/actions-account.ts's changePassword) so this
86	 * account is no weaker than one a customer created themselves.
87	 *
88	 * Also provisions this employee's own personal company mailbox (derived from
89	 * their first name, e.g. "Sadik" -> sadik@nxeon.cloud) and records it as
90	 * User.staffMailboxAddress — the mailbox they can always read/send from once
91	 * granted companyInbox, regardless of which OTHER mailboxes get added later
92	 * via StaffMailboxGrant (see lib/staff-mailbox-access.ts). Confirmed live
