316	/**
317	 * Removes a staff member's access. Not a hard delete — nothing in this
318	 * codebase deletes a User row (see adminSetUserSuspended in lib/actions.ts);
319	 * doing so here would orphan every AuditLog/WorkTask/ticket reply this
320	 * person's userId is attached to, which is exactly the accountability trail
321	 * the whole staff platform exists to keep. Instead: suspend (realUser()
322	 * already refuses suspended accounts, so this is an immediate, total lockout
323	 * — see lib/auth.ts), and additionally strip every StaffGrant/StaffIpAllow/
324	 * StaffMailboxGrant row so a future admin can't accidentally reactivate
325	 * someone into their old access just by flipping `suspended` back without
326	 * realizing grants were never re-reviewed. Their personal mailbox
327	 * (User.staffMailboxAddress) is left alone — it's still a real mailbox with
328	 * real mail in it, not something to delete as a side effect of an access
329	 * removal; an admin can delete it separately from Mailboxes if they want to.
330	 */
331	export async function deleteStaffAccount(userId: string): Promise<{ ok?: boolean; error?: string }> {
332	  const admin = await requireAdmin();
333	  if (userId === admin.id) return { error: "You can't remove your own access." };
334	
335	  const target = await requireStaffTarget(userId);
336	  if (!target) return { error: "User not found." };
337	
338	  if (target.role === "ADMIN") {
339	    const adminCount = await db.user.count({ where: { role: "ADMIN" } });
340	    if (adminCount <= 1) return { error: "Can't remove the last remaining admin account." };
341	  }
342	
343	  await db.$transaction([
344	    db.user.update({ where: { id: userId }, data: { suspended: true, sessionVersion: { increment: 1 } } }),
345	    db.staffGrant.deleteMany({ where: { userId } }),
346	    db.staffIpAllow.deleteMany({ where: { userId } }),
347	    db.staffMailboxGrant.deleteMany({ where: { userId } }),
348	  ]);
349	  await db.auditLog.create({
350	    data: { userId: admin.id, action: "staff.delete", detail: `${target.email} (was ${target.role})` },
351	  });
352	
353	  revalidatePath(`/admin/staff/${userId}`);
354	  revalidatePath("/admin/staff");
355	  return { ok: true };
356	}
