9	/**
10	 * Teams / Organizations — shared-account server actions.
11	 *
12	 * An Organization has one owner (User "OrgOwner") plus a set of Memberships.
13	 * Every actor is verified to hold a Membership of the required role in the
14	 * target org before any mutation runs, so a hand-crafted request can't touch
15	 * an org the caller doesn't belong to.
16	 *
17	 * WHAT A MEMBERSHIP ACTUALLY GRANTS (be precise — this used to be overstated):
18	 * visibility of the org roster, and, for OWNER/ADMIN, the right to invite,
19	 * re-role and remove members. It grants NOTHING ELSE. Servers, domains,
20	 * volumes, game servers, billing and invoices all remain scoped to the account
21	 * that owns them; no loader or action anywhere joins Membership to a resource.
22	 * The per-member "dashboard areas" control that used to sit on this page has
23	 * been removed rather than left in place: `Membership.areas` was written, echoed
24	 * back as saved, and read by nothing, so an owner who restricted a member to
25	 * Invoices was shown a restriction that did not exist. See lib/team-guard.ts for
26	 * why enforcing it for real is out of this change's reach, and the note rendered
27	 * in components/customer/TeamManager.tsx for what the customer is now told.
28	 *
29	 * CONSENT: `inviteMember` emails an invitation; only `acceptInvite`, run by the
30	 * invitee, creates a Membership. Nothing here can add a person to an org they
31	 * did not agree to join — see lib/team-guard.ts for the full rationale (it is
32	 * what fed the 2FA oracle, QA-PRELAUNCH P0-2).
33	 *
34	 * STILL OUT OF SCOPE: shared billing (org wallet / invoices) and members
35	 * inheriting access to shared servers. Deliberately absent, not half-built.
36	 */
37	
38	const ROLES = ["OWNER", "ADMIN", "MEMBER", "BILLING"] as const;
39	type OrgRole = (typeof ROLES)[number];
40	
41	function isRole(v: string): v is OrgRole {
42	  return (ROLES as readonly string[]).includes(v);
43	}
44	
45	/** Load the actor's membership in an org, or null if they aren't a member. */
46	async function actorMembership(orgId: string, userId: string) {
47	  if (!orgId) return null;
48	  return db.membership.findUnique({
49	    where: { orgId_userId: { orgId, userId } },
50	  });
51	}
