1	"use server";
2	
3	import { randomInt } from "crypto";
4	import { revalidatePath } from "next/cache";
5	import { z } from "zod";
6	import { db } from "./db";
7	import { requireUser } from "./auth";
8	import { requireArea } from "./rbac";
9	import { getSettingBool } from "./settings";
10	import type { User } from "@prisma/client";
11	
12	/** Alphabet for generated gift codes — no ambiguous chars (0/O, 1/I). */
13	const ALPHABET = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789";
14	
15	function randomSegment(len: number): string {
16	  let s = "";
17	  for (let i = 0; i < len; i++) s += ALPHABET[randomInt(ALPHABET.length)];
18	  return s;
19	}
20	
21	/** Generate a code like `NXEON-XXXX-XXXX`. */
22	function generateGiftCode(): string {
23	  return `NXEON-${randomSegment(4)}-${randomSegment(4)}`;
24	}
25	
26	/** Allocate a code that is unique in the DB (retry on the rare clash). */
27	async function uniqueGiftCode(): Promise<string> {
28	  for (let i = 0; i < 8; i++) {
29	    const code = generateGiftCode();
30	    const clash = await db.giftCode.findUnique({ where: { code } });
31	    if (!clash) return code;
32	  }
33	  // Extremely unlikely; add a third segment for extra entropy.
34	  return `${generateGiftCode()}-${randomSegment(4)}`;
35	}
36	
37	// ---------- Admin: create ----------
38	
39	const createSchema = z.object({
40	  amount: z.coerce.number().positive().max(10000),
41	  note: z.string().max(200).optional(),
42	  count: z.coerce.number().int().min(1).max(100),
43	});
44	
45	/**
46	 * Create one or more gift/credit codes. `amount` is dollars (converted to
47	 * cents), `count` bulk-generates N codes with the same amount/note.
48	 */
49	export async function adminCreateGiftCodes(
50	  prev: any,
51	  formData: FormData
52	): Promise<{ error?: string; ok?: boolean; codes?: string[] }> {
53	  const admin = await requireArea("billing");
54	  const rawNote = String(formData.get("note") ?? "").trim();
55	  const parsed = createSchema.safeParse({
56	    amount: formData.get("amount"),
57	    note: rawNote === "" ? undefined : rawNote,
58	    count: formData.get("count") || 1,
59	  });
60	  if (!parsed.success) {
61	    return { error: parsed.error.issues[0]?.message ?? "Invalid gift code details." };
62	  }
63	  const { amount, note, count } = parsed.data;
64	  const amountCents = Math.round(amount * 100);
65	  if (amountCents < 1) return { error: "Amount must be at least $0.01." };
66	
67	  const codes: string[] = [];
68	  for (let i = 0; i < count; i++) {
69	    const code = await uniqueGiftCode();
70	    await db.giftCode.create({
71	      data: { code, amountCents, note: note ?? null },
72	    });
73	    codes.push(code);
74	  }
75	
76	  await db.auditLog.create({
77	    data: {
78	      userId: admin.id,
79	      action: "admin.giftcode_create",
80	      detail: `${count} x $${amount.toFixed(2)}`,
81	    },
82	  });
83	  revalidatePath("/admin/gift-codes");
84	  return { ok: true, codes };
85	}
86	
87	// ---------- Admin: delete (unredeemed only) ----------
88	
89	export async function adminDeleteGiftCode(id: string): Promise<void> {
90	  const admin = await requireArea("billing");
91	  const gift = await db.giftCode.findUnique({ where: { id } });
92	  if (!gift) return;
93	  if (gift.redeemedById) return; // never delete a redeemed code
94	  await db.giftCode.delete({ where: { id } });
95	  await db.auditLog.create({
96	    data: { userId: admin.id, action: "admin.giftcode_delete", detail: gift.code },
97	  });
98	  revalidatePath("/admin/gift-codes");
99	}
100	
101	// ---------- Customer: redeem ----------
102	
103	/**
104	 * Redeem a gift code into the current user's wallet. Race-safe: the claim is an
105	 * `updateMany` guarded by `redeemedById: null` inside a transaction, so two
106	 * concurrent redemptions of the same code can only ever succeed once.
107	 */
108	export async function redeemGiftCode(
109	  rawCode: string
110	): Promise<{ ok?: boolean; error?: string; amountCents?: number }> {
111	  const user = await requireUser();
112	  const code = String(rawCode ?? "").trim().toUpperCase();
113	  if (!code) return { error: "Enter a gift code." };
114	
115	  const gift = await db.giftCode.findUnique({ where: { code } });
116	  // Not a single-use gift code? It might be a multi-use CREDIT_CENTS coupon
117	  // (e.g. a "free month" promo) — redeem that for wallet credit, no purchase.
118	  if (!gift) return redeemCreditCoupon(user, code);
119	  if (gift.redeemedById) return { error: "This code has already been redeemed." };
120	
121	  const result = await db.$transaction(async (tx) => {
122	    // Atomic claim: only succeeds if the code is still unredeemed.
123	    const claim = await tx.giftCode.updateMany({
124	      where: { id: gift.id, redeemedById: null },
125	      data: { redeemedById: user.id, redeemedAt: new Date() },
126	    });
127	    if (claim.count !== 1) return { error: "This code has already been redeemed." };
128	
129	    await tx.user.update({
130	      where: { id: user.id },
131	      data: { balanceCents: { increment: gift.amountCents } },
132	    });
133	    await tx.walletTransaction.create({
134	      data: {
135	        userId: user.id,
136	        amountCents: gift.amountCents,
137	        description: `Gift code redeemed (${gift.code})`,
138	      },
139	    });
140	    return { ok: true, amountCents: gift.amountCents };
141	  });
142	
143	  if (result.ok) {
144	    revalidatePath("/dashboard/billing");
145	  }
146	  return result;
147	}
148	
149	/**
150	 * Redeem a multi-use CREDIT_CENTS coupon (e.g. a "free month" promo) straight
151	 * into the wallet — no top-up/purchase required. Enforces enabled / active /
152	 * expiry / per-coupon `maxRedemptions` / one-per-user / first-time-only, all
153	 * race-safe: the limit is an atomic conditional increment, and the per-user cap
154	 * is the `@@unique([couponId,userId])` on CouponRedemption (a concurrent
155	 * double-redeem throws and rolls the whole transaction back).
156	 */
157	async function redeemCreditCoupon(
158	  user: User,
159	  code: string
160	): Promise<{ ok?: boolean; error?: string; amountCents?: number }> {
161	  if (!(await getSettingBool("coupons_enabled", true))) {
162	    return { error: "Promo codes are currently disabled." };
163	  }
164	  const coupon = await db.coupon.findUnique({ where: { code } });
165	  if (!coupon || !coupon.active) {
166	    return { error: "That code isn't valid. Check for typos and try again." };
167	  }
168	  if (coupon.kind !== "CREDIT_CENTS") {
169	    // PERCENT / FIXED_CENTS are discounts on a top-up, entered when adding funds.
170	    return { error: "This code is a discount on a top-up — enter it when you add funds." };
171	  }
172	  if (coupon.expiresAt && coupon.expiresAt.getTime() < Date.now()) {
173	    return { error: "This code has expired." };
174	  }
175	  if (coupon.maxRedemptions !== null && coupon.timesRedeemed >= coupon.maxRedemptions) {
176	    return { error: "This code has reached its redemption limit." };
177	  }
178	  const already = await db.couponRedemption.findUnique({
179	    where: { couponId_userId: { couponId: coupon.id, userId: user.id } },
180	  });
181	  if (already) return { error: "You've already used this code." };
182	  if (coupon.firstTimeOnly) {
183	    const priorCredits = await db.walletTransaction.count({
184	      where: { userId: user.id, amountCents: { gt: 0 } },
185	    });
186	    if (priorCredits > 0) return { error: "This code is for first-time customers only." };
187	  }
188	
189	  const result = await db
190	    .$transaction(async (tx) => {
191	      // Atomic limit claim — only proceeds while under the cap (skipped if uncapped).
192	      if (coupon.maxRedemptions !== null) {
193	        const claim = await tx.coupon.updateMany({
194	          where: { id: coupon.id, timesRedeemed: { lt: coupon.maxRedemptions } },
195	          data: { timesRedeemed: { increment: 1 } },
196	        });
197	        if (claim.count !== 1) return { error: "This code has reached its redemption limit." };
198	      } else {
199	        await tx.coupon.update({ where: { id: coupon.id }, data: { timesRedeemed: { increment: 1 } } });
200	      }
201	      // One-per-user via the unique constraint (a race throws → full rollback).
202	      await tx.couponRedemption.create({
203	        data: { couponId: coupon.id, userId: user.id, amountCents: coupon.value, context: "free-credit" },
204	      });
205	      await tx.user.update({
206	        where: { id: user.id },
207	        data: { balanceCents: { increment: coupon.value } },
208	      });
209	      await tx.walletTransaction.create({
210	        data: { userId: user.id, amountCents: coupon.value, description: `Promo code redeemed (${coupon.code})` },
211	      });
212	      return { ok: true, amountCents: coupon.value };
213	    })
214	    .catch(() => ({ error: "You've already used this code." }) as { error: string });
215	
216	  if ("ok" in result && result.ok) revalidatePath("/dashboard/billing");
217	  return result;
218	}
