282	async function generateDemoForProspect(
283	  prospect: ProspectRow,
284	  opts: { extraction?: ScrapeResult["extraction"]; pastedTextOverride?: string } = {}
285	): Promise<ActionState> {
286	  const vertical = prospect.vertical || "dentist";
287	  const dbVertical = await db.agencyVertical.findUnique({
288	    where: { slug: vertical },
289	    include: { templates: { orderBy: { createdAt: "asc" }, take: 1 } },
290	  });
291	  const template = dbVertical?.templates[0] ?? null;
292	  const structure = template ? asTemplateStructure(template.structure) : undefined;
293	  const slug = slugify(prospect.businessName);
294	  const pastedSiteText = (opts.pastedTextOverride ?? prospect.pastedSiteText ?? "").slice(0, 6000);
295	
296	  let ir: SiteIR;
297	  let genMode = "fallback";
298	  let genModel = "";
299	  let genOk = true;
300	  let genMsg = "";
301	  try {
302	    const result = await generateSiteIR({
303	      businessName: prospect.businessName,
304	      vertical,
305	      slug,
306	      pastedSiteText,
307	      structure,
308	    });
309	    ir = result.ir;
310	    genMode = result.mode;
311	    genModel = result.model;
312	    genOk = result.ok;
313	    genMsg = result.message;
314	  } catch (err) {
315	    await logEvent("error", "agency.demo.generate", { message: String(err), prospectId: prospect.id });
316	    return { error: "Generation failed. Please try again." };
317	  }
318	
319	  const rendered = renderSiteHtml(ir);
320	  if (!rendered.guardrailsOk) {
321	    await logEvent("error", "agency.demo.guardrails", { prospectId: prospect.id, message: "guardrail assertion failed" });
322	    return { error: "Render failed a legal guardrail check and was not saved." };
323	  }
324	
325	  try {
326	    const demo = await db.agencyDemoSite.create({
327	      data: {
328	        prospectId: prospect.id,
329	        templateId: template?.id ?? null,
330	        siteIR: ir as unknown as Prisma.InputJsonValue,
331	        renderedHtml: rendered.html,
332	        extractionJson: (opts.extraction ?? {}) as unknown as Prisma.InputJsonValue,
333	        slug,
334	        status: "GENERATED",
335	        noindex: true,
336	      },
337	    });
338	    await db.agencyGenerationLog.create({
339	      data: { demoId: demo.id, mode: genMode, model: genModel, ok: genOk, message: genMsg.slice(0, 500) },
340	    });
341	    await db.agencyActivity.create({
342	      data: {
343	        prospectId: prospect.id,
344	        kind: "DEMO",
345	        body: `Generated demo (${genMode})${opts.extraction ? " from scrape" : ""}.`,
346	        meta: { demoId: demo.id, mode: genMode } as Prisma.InputJsonValue,
347	      },
348	    });
349	    if (prospect.status === "PROSPECT") {
350	      await db.agencyProspect.update({ where: { id: prospect.id }, data: { status: "GENERATED" } });
351	    }
352	  } catch (err) {
353	    await logEvent("error", "agency.demo.persist", { message: String(err), prospectId: prospect.id });
354	    return { error: "Could not save the generated demo." };
355	  }
356	
357	  revalidatePath("/admin/agency/demos");
358	  revalidatePath("/admin/agency/prospects");
359	  revalidatePath(`/admin/agency/prospects/${prospect.id}`);
360	  revalidatePath("/admin/agency");
361	  return { ok: true };
