68	/**
69	 * Finish saving a card after Stripe redirects back.
70	 *
71	 * Safe to call repeatedly with the same session id — it re-reads the same payment
72	 * method from Stripe and writes the same columns, so a refreshed tab is a no-op
73	 * rather than a second card.
74	 */
75	export async function finalizeCardSetup(
76	  sessionId: string,
77	): Promise<{ ok?: boolean; label?: string; error?: string }> {
78	  await assertNotImpersonating();
79	  const user = await requireUser();
80	  if (!sessionId) return { error: "Missing card setup reference." };
81	
82	  const res = await saveCardFromSetupSession(sessionId, user.id);
83	  if (res.error || !res.card) return { error: res.error ?? "The card wasn't saved." };
84	
85	  const label = cardDisplayLabel(res.card) ?? "Card saved";
86	  await db.auditLog.create({ data: { userId: user.id, action: "card.saved", detail: label } });
87	  // Anyone mid-dunning was told we'd charge a new card straight away; make it true.
