5	 * confirm() call throws instead of returning a clean decline — see
6	 * `createHostedFallbackFromSession` (lib/stripe.ts) for why that specific
7	 * signal means "the iframe itself likely broke," not "the bank said no."
8	 *
9	 * Deliberately narrow: this is not offered proactively, and not on every
10	 * payment error — components/customer/PaymentStep.tsx only calls it from its
11	 * catch block (an unexpected exception), never from a clean
12	 * `result.type === "error"` decline, where the existing "try another card"
13	 * messaging is already correct.
14	 */
15	import { requireUser } from "./auth";
16	import { stripe, stripeConfigured, createHostedFallbackFromSession } from "./stripe";
