18	export async function getHostedCheckoutFallback(
19	  sessionId: string
20	): Promise<{ ok: true; url: string } | { ok: false; error: string }> {
21	  if (!stripeConfigured()) return { ok: false, error: "Payments are not configured." };
22	  if (typeof sessionId !== "string" || !/^cs_[a-zA-Z0-9_]+$/.test(sessionId)) {
23	    return { ok: false, error: "Invalid session." };
24	  }
25	  try {
26	    const user = await requireUser();
27	    // Ownership check: the session's own metadata must name THIS user — the
28	    // same field every `createXCheckout` function already stamps on every
29	    // order type, so this one check covers all of them generically.
30	    const original = await stripe().checkout.sessions.retrieve(sessionId);
31	    if (original.metadata?.nxeonUserId !== user.id) {
32	      return { ok: false, error: "Session not found." };
33	    }
34	    const fallback = await createHostedFallbackFromSession(sessionId);
35	    if (!fallback) return { ok: false, error: "This order can no longer be retried — it may already be paid or expired." };
36	    return { ok: true, url: fallback.url };
37	  } catch (err) {
38	    console.error("[payment-fallback] getHostedCheckoutFallback failed", err);
39	    return { ok: false, error: "Could not create a payment link. Please try again." };
40	  }
41	}
