2	
3	import { revalidatePath } from "next/cache";
4	import { db } from "./db";
5	import { requireUser, assertNotImpersonating } from "./auth";
6	import { InsufficientBalanceError } from "./wallet";
7	import { dedicatedIpPurchaseQuote, applyDedicatedIpPurchase, DedicatedIpPurchaseError } from "./dedicated-ip-purchase";
8	import { createDedicatedIpCheckout, type EmbeddedCheckout } from "./stripe";
9	import { walletSplit } from "./wallet-split";
10	import { emailVerificationError } from "./email-verification";
11	
12	/**
13	 * Post-deploy "Add dedicated IP": give an ALREADY-provisioned server (VPS or
14	 * game) its own dedicated public IPv4, for a server that doesn't already have
15	 * one. Money path is a carbon copy of lib/actions-disk.ts expandServerDisk:
16	 *   quote -> walletSplit -> (card remainder ? Stripe checkout : apply now).
17	 * The wallet is only ever debited by applyDedicatedIpPurchase, and only after
18	 * the card portion has cleared, so displayed === charged and nothing is
19	 * charged twice. The actual IP claim + network reconfiguration happens
20	 * asynchronously in the worker (ASSIGN_DEDICATED_IP) — see
21	 * lib/dedicated-ip-purchase.ts's header for why that split is deliberate.
22	 */
23	async function ownedServer(serverId: string) {
24	  const user = await requireUser();
25	  const server = await db.server.findUnique({ where: { id: serverId }, include: { dedicatedIp: true } });
26	  if (!server) throw new Error("Not found");
27	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
28	  return { user, server };
29	}
30	
31	export async function purchaseDedicatedIp(
32	  serverId: string,
33	  useWallet: boolean = true,
34	): Promise<{ error?: string; checkout?: EmbeddedCheckout }> {
35	  // Spend path: block wallet debits while an admin is impersonating — same
36	  // guard as every other money movement on a server (resizeServer,
37	  // expandServerDisk).
38	  await assertNotImpersonating();
39	  const { user, server } = await ownedServer(serverId);
40	  // Purchase gate: this is an irreversible real-infra charge. See
41	  // lib/email-verification.ts.
42	  const unverified = await emailVerificationError(user);
43	  if (unverified) return { error: unverified };
44	
45	  if (server.dedicatedIp) return { error: "This server already has a dedicated IP." };
46	
47	  // Reject while another job is in flight, and only from a steady run state.
48	  // (applyDedicatedIpPurchase re-checks both; this returns the friendlier
49	  // message first.)
50	  if (!["RUNNING", "STOPPED"].includes(server.status)) {
51	    return { error: "Server must be running or stopped to add a dedicated IP." };
52	  }
53	  const pending = await db.job.count({ where: { serverId, status: { in: ["QUEUED", "RUNNING"] } } });
54	  if (pending > 0) return { error: "Another operation is already in progress on this server." };
55	
56	  let quote;
57	  try {
58	    quote = await dedicatedIpPurchaseQuote(serverId);
59	  } catch (e) {
60	    if (e instanceof DedicatedIpPurchaseError) return { error: e.message };
61	    throw e;
62	  }
63	  const { prorateCents } = quote;
64	
65	  // Wallet-aware split — identical logic to the resize/disk-expand flows.
66	  // AddDedicatedIp computes the same split (lib/wallet-split.ts) so
67	  // displayed === charged.
68	  const { cardCents } = walletSplit({
69	    dueCents: prorateCents,
70	    balanceCents: user.balanceCents,
71	    useWallet,
72	  });
73	
74	  if (cardCents > 0) {
75	    const checkout = await createDedicatedIpCheckout(user, cardCents, {
76	      serverId,
77	      hostname: server.hostname,
78	      prorateCents,
79	    });
80	    if (!checkout) {
81	      return {
82	        error: `A dedicated IP costs $${(prorateCents / 100).toFixed(2)} for the rest of your term, and card payments aren't set up — top up your wallet first.`,
83	      };
84	    }
85	    return { checkout };
86	  }
87	
88	  try {
89	    await applyDedicatedIpPurchase({ serverId, actorUserId: user.id });
90	  } catch (e) {
91	    if (e instanceof DedicatedIpPurchaseError) return { error: e.message };
92	    if (e instanceof InsufficientBalanceError) return { error: "Insufficient balance — top up your wallet first." };
93	    throw e;
94	  }
95	  revalidatePath(`/dashboard/servers/${serverId}`);
96	  return {};
