3	/**
4	 * Customer self-service Discord-account linking — status + disconnect for
5	 * the dashboard Settings → Integrations "Discord" card. The "Connect" side
6	 * is a plain redirect to app/api/discord/authorize/route.ts (a GET route,
7	 * not a server action, since it has to 302 to Discord).
8	 *
9	 * Deliberately separate from lib/actions-discord-link.ts (the STAFF
10	 * version, gated on requireArea("support") for the ticket-reply-attribution
11	 * flow) — this one is gated by plain requireUser(), any signed-in account.
12	 */
13	
14	import { revalidatePath } from "next/cache";
15	import { db } from "./db";
16	import { requireUser } from "./auth";
17	import { checkRateLimit } from "./rate-limit";
18	import { getDiscordUserById } from "./discord";
19	import { discordOauthConfigured } from "./discord-oauth";
20	import { syncDiscordRoles } from "./discord-roles";
21	
22	export type CustomerDiscordLinkStatus = {
23	  connected: boolean;
24	  username: string | null;
25	  oauthAvailable: boolean;
26	};
27	
28	export async function getMyDiscordLinkStatus(): Promise<CustomerDiscordLinkStatus> {
29	  const user = await requireUser();
30	  const row = await db.user.findUnique({ where: { id: user.id }, select: { discordUserId: true } as any });
31	  const discordUserId = (row as any)?.discordUserId as string | null | undefined;
32	  const oauthAvailable = await discordOauthConfigured();
33	  if (!discordUserId) return { connected: false, username: null, oauthAvailable };
34	  const profile = await getDiscordUserById(discordUserId);
35	  return { connected: true, username: profile?.username ?? null, oauthAvailable };
36	}
37	
38	export async function disconnectMyDiscordLink(): Promise<{ ok?: boolean; error?: string }> {
39	  const user = await requireUser();
40	  const rl = checkRateLimit(`discord-unlink:${user.id}`, { max: 10, windowMs: 60_000 });
41	  if (!rl.ok) return { error: `Too many attempts — try again in ${rl.retryAfterSec}s.` };
42	
43	  await db.user.update({ where: { id: user.id }, data: { discordUserId: null } as any });
44	  await db.auditLog.create({ data: { userId: user.id, action: "discord.unlink" } }).catch(() => {});
45	  revalidatePath("/dashboard/settings");
46	  return { ok: true };
47	}
48	
49	/** Manually re-run role sync (e.g. right after a purchase, from a "refresh" button) — best-effort. */
50	export async function refreshMyDiscordRoles(): Promise<{ ok: true }> {
51	  const user = await requireUser();
52	  void syncDiscordRoles(user.id);
53	  return { ok: true };
54	}
